import copy


def save_member(members, profile, member_id=None):
    if not isinstance(members, list):
        raise TypeError("members must be a list")

    def validate_member(value, has_id):
        expected = {"handle", "email", "secret", "avatar", "tags"}
        if has_id:
            expected.add("id")
        if not isinstance(value, dict) or set(value) != expected:
            raise ValueError("malformed member")
        if has_id and (not isinstance(value["id"], int) or isinstance(value["id"], bool) or value["id"] <= 0):
            raise ValueError("invalid ID")
        for key in ("handle", "email", "secret"):
            if not isinstance(value[key], str) or not value[key].strip():
                raise ValueError("invalid text field")
        if value["avatar"] is not None and not isinstance(value["avatar"], str):
            raise ValueError("invalid avatar")
        if not isinstance(value["tags"], list) or any(not isinstance(tag, str) for tag in value["tags"]):
            raise ValueError("invalid tags")

    for member in members:
        validate_member(member, True)
    validate_member(profile, False)
    ids = [member["id"] for member in members]
    if len(ids) != len(set(ids)):
        raise ValueError("duplicate ID")
    if member_id is not None:
        if not isinstance(member_id, int) or isinstance(member_id, bool):
            raise ValueError("invalid member ID")
        if member_id not in ids:
            raise ValueError("unknown member ID")

    normalized_handle = profile["handle"].strip()
    normalized_email = profile["email"].strip()
    for member in members:
        if member["id"] == member_id:
            continue
        if member["handle"].strip() == normalized_handle:
            raise ValueError("duplicate handle")
        if member["email"].strip() == normalized_email:
            raise ValueError("duplicate email")

    assigned_id = member_id if member_id is not None else (max(ids, default=0) + 1)
    tags = []
    for tag in profile["tags"]:
        if tag not in tags:
            tags.append(tag)
    saved = {
        "id": assigned_id,
        "handle": profile["handle"].strip(),
        "email": profile["email"].strip(),
        "secret": profile["secret"].strip(),
        "avatar": profile["avatar"],
        "tags": tags,
    }
    result = [copy.deepcopy(member) for member in members if member["id"] != assigned_id]
    result.append(saved)
    return sorted(result, key=lambda member: member["id"])

